questionvariables.text:
/* Valid Pythagorean triples [base, height, hypotenuse(slant)] */
triples : [[3,4,5], [4,3,5], [6,8,10], [8,6,10], [5,12,13], [9,12,15], [12,9,15]];
triple : rand(triples);

/* Assign strictly valid geometry variables */
diff_single : triple[1];
h : triple[2];
slant : triple[3];

b : rand(8) + 6; /* Top base */
a : b + (2 * diff_single); /* Bottom base */

/* Pre-calculated steps for the worked solution */
diff_single_sq : diff_single^2;
slant_sq : slant^2;
h_sq : h^2;
sum_ab : a + b;

/* Area (Will always be a clean integer due to standard triples) */
ta1 : (1/2) * sum_ab * h;

/* Mistakes */
m1 : sum_ab * h; /* Forgot 1/2 */
m2 : (1/2) * sum_ab * slant; /* Used slant instead of height */
m3 : (1/2) * (a + b + 2*slant) * h; /* Perimeter confusion */
